<template>
 <el-dialog v-model="visible" title="版本差异对比 · 只读" width="min(1280px,calc(100vw - 24px))" append-to-body destroy-on-close @closed="close">
  <el-alert title="比较已保存的版本。绿色为新增、红色为删除；HTML与图片标记始终按文字显示，不执行脚本。此操作不会保存、恢复、审核或发布。" :closable="false"/>
  <el-form inline style="margin-top:14px" @submit.prevent="compare">
   <el-form-item label="原版本"><el-select v-model="leftKey" style="width:300px"><el-option v-for="o in choices" :key="o.key" :label="o.label" :value="o.key"/></el-select></el-form-item>
   <el-form-item label="新版本"><el-select v-model="rightKey" style="width:300px"><el-option v-for="o in choices" :key="o.key" :label="o.label" :value="o.key"/></el-select></el-form-item>
   <el-form-item><el-button type="primary" :loading="busy" @click="compare">比较</el-button><el-button :disabled="busy||!hasMore" @click="more">更多历史/送审版本</el-button></el-form-item>
  </el-form><el-checkbox v-model="onlyChanged">只看变化字段</el-checkbox><p v-if="result">{{result.leftLabel}} → {{result.rightLabel}}，{{result.changedCount}}个字段有变化</p>
  <el-alert v-for="notice in result?.notices||[]" :key="notice" :title="notice" type="info" :closable="false" style="margin:10px 0"/><el-table :data="shown" v-loading="busy" max-height="55vh" border><el-table-column label="字段" width="175"><template #default="s">{{fieldLabel(s.row.label)}}<el-tag v-if="s.row.coarse" type="info">整段替换</el-tag></template></el-table-column><el-table-column label="变化详情" min-width="420"><template #default="s"><div class="diff"><span v-for="(p,i) in s.row.parts" :key="i" :class="p.op">{{p.text}}</span></div></template></el-table-column><el-table-column label="原值" min-width="220"><template #default="s"><pre>{{s.row.left||'（空）'}}</pre></template></el-table-column><el-table-column label="新值" min-width="220"><template #default="s"><pre>{{s.row.right||'（空）'}}</pre></template></el-table-column><template #empty>当前选择没有字段差异</template></el-table>
  <template #footer><el-button @click="visible=false">关闭</el-button></template>
 </el-dialog>
</template>
<script setup>
import{ref,computed,onBeforeUnmount,onDeactivated}from'vue';import{workflow}from'@/api/cms/workflow'
const visible=ref(false),busy=ref(false),choices=ref([]),leftKey=ref(''),rightKey=ref(''),result=ref(),onlyChanged=ref(true),hasMore=ref(false);let epoch=0,page=1,ctx={},seed=[]
const shown=computed(()=>result.value?.fields.filter(x=>!onlyChanged.value||x.changed)||[])
const labels={siteName:'站点名称',slogan:'简介',theme:'模板',palette:'配色',density:'密度',fontScale:'字号',frameWidth:'宽度',radius:'圆角',logoAssetId:'Logo',iconAssetId:'图标',footer:'页脚',phone:'电话',email:'邮箱',navigation:'导航',banners:'轮播',blocks:'首页组件',items:'条目',label:'名称',title:'标题',text:'文字',url:'链接',contentId:'内容ID',assetId:'素材ID',enabled:'启用',kind:'类型',channelId:'栏目ID',count:'条数',layout:'布局',featuredOnly:'仅推荐',tagIds:'标签ID',tags:'标签快照',relatedIds:'关联内容',featured:'推荐',pinOrder:'置顶顺序',shareTitle:'分享标题',shareDescription:'分享描述',shareAssetId:'分享图片',analyticsEnabled:'访问统计',analyticsKeywords:'搜索词记录',analyticsRetention:'统计保留天数',listingLayout:'默认列表布局',channelLayouts:'栏目布局'}
function fieldLabel(v){return v.replace(/[a-zA-Z][a-zA-Z0-9]*/g,s=>labels[s]||s)}
const key=r=>r.source+':'+(r.id||0);function add(o){if(!choices.value.some(c=>c.key===o.key))choices.value.push(o)}
async function open(input){close();ctx={...input,kind:input.kind.toUpperCase()};visible.value=true;busy.value=true;const n=epoch;try{const d=(await workflow(ctx.kind==='SITE'?'site':`${ctx.kind.toLowerCase()}/${ctx.objectId}`)).data;if(n!==epoch)return;ctx.version=d.version;add({key:'DRAFT:0',label:'当前已保存草稿（工作版本'+d.version+'）',ref:{source:'DRAFT',id:0,version:d.version}});seed=[input.left,input.right].filter(Boolean);for(const ref of seed)add({key:key(ref),label:(ref.source==='REVIEW'?'送审快照 #':ref.source==='RELEASE'?'外观发布版 #':'历史修订 #')+ref.id,ref});await loadRefs();if(n!==epoch)return;leftKey.value=input.left?key(input.left):(choices.value.find(x=>x.ref.source!=='DRAFT'&&(x.ref.source!=='REVISION'||x.ref.id!==d.workingRevisionId))?.key||choices.value.find(x=>x.ref.source!=='DRAFT')?.key||'DRAFT:0');rightKey.value=input.right?key(input.right):'DRAFT:0';await compare()}finally{if(n===epoch)busy.value=false}}
async function loadRefs(){const n=epoch,[h,r]=await Promise.all([workflow(ctx.kind==='SITE'?'site/history':`${ctx.kind.toLowerCase()}/${ctx.objectId}/history`,'get',undefined,{pageNum:page,pageSize:20}),workflow('review/object','get',undefined,{kind:ctx.kind,objectId:ctx.objectId,pageNum:page,pageSize:20})]);if(n!==epoch)return;for(const row of h.rows){const source=ctx.kind==='SITE'?'RELEASE':'REVISION',id=ctx.kind==='SITE'?row.releaseId:row.revisionId;add({key:source+':'+id,label:(ctx.kind==='SITE'?'外观发布版 #':'历史修订'+row.revisionNo+' #')+id,ref:{source,id,version:0}})};for(const row of r.rows)add({key:'REVIEW:'+row.reviewId,label:'送审 #'+row.reviewId+' · '+row.status,ref:{source:'REVIEW',id:row.reviewId,version:0}});hasMore.value=page*20<h.total||page*20<r.total}
async function more(){page++;await loadRefs()}
async function compare(){if(!leftKey.value||!rightKey.value)return;const n=epoch;busy.value=true;try{const a=choices.value.find(o=>o.key===leftKey.value).ref,b=choices.value.find(o=>o.key===rightKey.value).ref;const r=await workflow('compare','post',{kind:ctx.kind,objectId:ctx.objectId,left:a,right:b});if(n===epoch)result.value=r.data}finally{if(n===epoch)busy.value=false}}
function close(){++epoch;visible.value=false;busy.value=false;choices.value=[];result.value=null;hasMore.value=false;page=1;ctx={};seed=[]}onBeforeUnmount(close);onDeactivated(close);defineExpose({open,close})
</script><style scoped>pre,.diff{white-space:pre-wrap;overflow-wrap:anywhere;max-height:340px;overflow:auto;margin:0}.insert{background:#dcfce7;color:#166534}.delete{background:#fee2e2;color:#991b1b;text-decoration:line-through}.equal{color:var(--el-text-color-regular)}</style>
